        public void Set(Parser paser)
        {
            var ty =  Data1.Length - 1;
            for (int i = 0; i < Data1.Length; i++)
            {
                foreach (var item2 in Data1[i].Item1)
                {
                    paser.global_name.Add(item2);
                    paser.global_name2.Add((Data1[i].Item2, Data[ty - i]));
                }
            }
            for (int i = 0; i < Data2.Length; i++)
            {
                foreach (var item2 in Data2[i].Item1)
                {
                    paser.global_name.Add(item2);
                    paser.global_name2.Add((Data2[i].Item2, Data[Data1.Length + i]));
                }
            }
        }
        //VARI : name ad-valu     ad-type
        //FUNC : name ad-call-str ad-type(return  "void" or "value" or "array")

        //順番で管理
        public Header(byte outType)
        {
            Type = outType;
            Data = new(Data1.Length + Data2.Length);
            for (int i = Data1.Length - 1; i >= 0; i--)
            {
                Data.Add(new(Data1[i], (outType is 0x10) ? Js1[i] : Asm1[i], false));
            }
            for (int i = 0; i < Data2.Length; i++)
            {
                Data.Add(new(Data2[i], (outType is 0x10) ? Js2[i] : Asm2[i], (Data2[i].Item1[0] is "TextArray_MarkText")));
            }
        }

